    content: "[\n  {\n    \"name\": \"theme_info\",\n    \"theme_name\": \"Gbox Default\",\n    \"theme_version\": \"0.1.0\",\n    \"theme_author\": \"Gbox Platform\",\n    \"theme_documentation_url\": \"https://github.com/GBox-Company/gbox-theme-editor\",\n    \"theme_support_email\": \"support@gbox.co\"\n  },\n  {\n    \"name\": \"Brand\",\n    \"settings\": [\n      { \"type\": \"header\",       \"content\": \"Logo + favicon\" },\n      { \"type\": \"image_picker\", \"id\": \"logo\",     \"label\": \"Logo\" },\n      { \"type\": \"image_picker\", \"id\": \"favicon\",  \"label\": \"Favicon\", \"info\": \"32×32 PNG recommended\" },\n      { \"type\": \"image_picker\", \"id\": \"og_image\", \"label\": \"Default Open Graph image\", \"info\": \"1200×630 — used when a page has no specific share image\" }\n    ]\n  },\n  {\n    \"name\": \"Colors\",\n    \"settings\": [\n      { \"type\": \"header\", \"content\": \"Brand colors\" },\n      { \"type\": \"color\",  \"id\": \"color_primary\",   \"label\": \"Primary\",    \"default\": \"#6366f1\" },\n      { \"type\": \"color\",  \"id\": \"color_secondary\", \"label\": \"Secondary\",  \"default\": \"#10b981\" },\n      { \"type\": \"color\",  \"id\": \"color_accent\",    \"label\": \"Accent\",     \"default\": \"#f59e0b\" },\n      { \"type\": \"header\", \"content\": \"Surfaces\" },\n      { \"type\": \"color\",  \"id\": \"color_bg\",        \"label\": \"Background\", \"default\": \"#ffffff\" },\n      { \"type\": \"color\",  \"id\": \"color_text\",      \"label\": \"Text\",       \"default\": \"#1e293b\" },\n      { \"type\": \"color\",  \"id\": \"color_border\",    \"label\": \"Border\",     \"default\": \"#e2e8f0\" },\n      { \"type\": \"header\", \"content\": \"Mode\" },\n      {\n        \"type\": \"select\",\n        \"id\": \"color_scheme\",\n        \"label\": \"Default scheme\",\n        \"options\": [\n          { \"value\": \"light\", \"label\": \"Light\" },\n          { \"value\": \"dark\",  \"label\": \"Dark\"  },\n          { \"value\": \"auto\",  \"label\": \"Match device preference\" }\n        ],\n        \"default\": \"light\"\n      }\n    ]\n  },\n  {\n    \"name\": \"Typography\",\n    \"settings\": [\n      {\n        \"type\": \"font_picker\",\n        \"id\": \"font_heading\",\n        \"label\": \"Heading font\",\n        \"default\": \"Inter\"\n      },\n      {\n        \"type\": \"font_picker\",\n        \"id\": \"font_body\",\n        \"label\": \"Body font\",\n        \"default\": \"Inter\"\n      },\n      {\n        \"type\": \"range\",\n        \"id\": \"font_body_size\",\n        \"label\": \"Body size (px)\",\n        \"min\": 12,\n        \"max\": 20,\n        \"step\": 1,\n        \"default\": 16\n      },\n      {\n        \"type\": \"range\",\n        \"id\": \"heading_scale\",\n        \"label\": \"Heading scale\",\n        \"min\": 1.1,\n        \"max\": 1.6,\n        \"step\": 0.05,\n        \"default\": 1.25,\n        \"info\": \"Multiplier between H1 → H6 sizes\"\n      }\n    ]\n  },\n  {\n    \"name\": \"Buttons\",\n    \"settings\": [\n      { \"type\": \"range\", \"id\": \"button_radius\", \"label\": \"Corner radius (px)\", \"min\": 0, \"max\": 32, \"step\": 1, \"default\": 6 },\n      { \"type\": \"range\", \"id\": \"button_weight\", \"label\": \"Font weight\",        \"min\": 400, \"max\": 700, \"step\": 100, \"default\": 500 },\n      {\n        \"type\": \"select\",\n        \"id\": \"button_style\",\n        \"label\": \"Style\",\n        \"options\": [\n          { \"value\": \"solid\",   \"label\": \"Solid\"   },\n          { \"value\": \"outline\", \"label\": \"Outline\" },\n          { \"value\": \"ghost\",   \"label\": \"Ghost\"   }\n        ],\n        \"default\": \"solid\"\n      }\n    ]\n  },\n  {\n    \"name\": \"Cards\",\n    \"settings\": [\n      { \"type\": \"range\",    \"id\": \"card_radius\", \"label\": \"Corner radius (px)\",  \"min\": 0, \"max\": 32, \"step\": 1, \"default\": 8 },\n      { \"type\": \"select\",   \"id\": \"card_shadow\", \"label\": \"Shadow\",\n        \"options\": [\n          { \"value\": \"none\",   \"label\": \"None\"   },\n          { \"value\": \"subtle\", \"label\": \"Subtle\" },\n          { \"value\": \"medium\", \"label\": \"Medium\" },\n          { \"value\": \"strong\", \"label\": \"Strong\" }\n        ], \"default\": \"subtle\"\n      },\n      { \"type\": \"checkbox\", \"id\": \"card_show_vendor\", \"label\": \"Show vendor on product cards\",  \"default\": false },\n      { \"type\": \"checkbox\", \"id\": \"card_show_rating\", \"label\": \"Show rating stars on product cards\", \"default\": true }\n    ]\n  },\n  {\n    \"name\": \"Cart\",\n    \"settings\": [\n      {\n        \"type\": \"select\",\n        \"id\": \"cart_type\",\n        \"label\": \"Cart type\",\n        \"options\": [\n          { \"value\": \"drawer\", \"label\": \"Drawer (slide-in)\" },\n          { \"value\": \"page\",   \"label\": \"Page\" },\n          { \"value\": \"popup\",  \"label\": \"Popup\" }\n        ],\n        \"default\": \"drawer\"\n      },\n      { \"type\": \"checkbox\", \"id\": \"cart_show_note\",     \"label\": \"Allow order note\",     \"default\": true },\n      { \"type\": \"checkbox\", \"id\": \"cart_show_subtotal\", \"label\": \"Show subtotal in icon\", \"default\": true }\n    ]\n  },\n  {\n    \"name\": \"Social media\",\n    \"settings\": [\n      { \"type\": \"header\", \"content\": \"Profile URLs (leave blank to hide icon)\" },\n      { \"type\": \"url\", \"id\": \"social_facebook\",  \"label\": \"Facebook\"  },\n      { \"type\": \"url\", \"id\": \"social_instagram\", \"label\": \"Instagram\" },\n      { \"type\": \"url\", \"id\": \"social_tiktok\",    \"label\": \"TikTok\"    },\n      { \"type\": \"url\", \"id\": \"social_youtube\",   \"label\": \"YouTube\"   },\n      { \"type\": \"url\", \"id\": \"social_x\",         \"label\": \"X (Twitter)\" }\n    ]\n  },\n  {\n    \"name\": \"Custom code\",\n    \"settings\": [\n      {\n        \"type\": \"paragraph\",\n        \"content\": \"Paste tweaks below. Loaded on every page. Saving here does not require touching the theme files.\"\n      },\n      { \"type\": \"html\", \"id\": \"custom_css\", \"label\": \"Custom CSS\", \"info\": \"Wrapped in <style>…</style>\"  },\n      { \"type\": \"html\", \"id\": \"custom_js\",  \"label\": \"Custom JS\",  \"info\": \"Wrapped in <script>…</script>; runs after DOMContentLoaded\" }\n    ]\n  }\n]\n",
